// Interface for all notification types
interface NotificationSender {
    void send(String message, String recipient);
}

// Concrete implementations
class EmailSender implements NotificationSender {
    public void send(String message, String recipient) {
        System.out.println("Email to " + recipient + ": " + message);
    }
}

class SmsSender implements NotificationSender {
    public void send(String message, String recipient) {
        System.out.println("SMS to " + recipient + ": " + message);
    }
}

// Factory that decides which sender to create
class NotificationFactory {
    public static NotificationSender createSender(String channel) {
        return switch (channel.toLowerCase()) {
            case "email" -> new EmailSender();
            case "sms" -> new SmsSender();
            default -> throw new IllegalArgumentException("Unknown channel: " + channel);
        }; // Switch expression returns the sender directly
    }
}

// Client code never uses 'new' directly
var sender = NotificationFactory.createSender("email");
sender.send("Your order shipped!", "user@example.com");

import org.springframework.context.annotation.*;
import org.springframework.stereotype.Service;

@Configuration
class AppConfig {
    @Bean
    public PaymentProcessor paymentProcessor() {
        return new StripePaymentProcessor(); // Factory method for bean
    }
}

@Service
class OrderService {
    private final PaymentProcessor processor;

    public OrderService(PaymentProcessor processor) {
        this.processor = processor; // Injected by Spring's factory
    }

    public void checkout(String orderId) {
        processor.processPayment(orderId);
    }
}

// In main or test
var context = new AnnotationConfigApplicationContext(AppConfig.class);
var orderService = context.getBean(OrderService.class); // Factory retrieves bean
orderService.checkout("ORDER123");
// Spring's BeanFactory created PaymentProcessor, then injected it into OrderService

interface Button { void render(); }
interface TextField { void render(); }

class WindowsButton implements Button {
    public void render() { System.out.println("Rendering Windows button"); }
}

class MacOSButton implements Button {
    public void render() { System.out.println("Rendering macOS button"); }
}

class WindowsTextField implements TextField {
    public void render() { System.out.println("Rendering Windows text field"); }
}

class MacOSTextField implements TextField {
    public void render() { System.out.println("Rendering macOS text field"); }
}

interface GUIFactory {
    Button createButton();
    TextField createTextField();
}

class WindowsFactory implements GUIFactory {
    public Button createButton() { return new WindowsButton(); }
    public TextField createTextField() { return new WindowsTextField(); }
}

class MacOSFactory implements GUIFactory {
    public Button createButton() { return new MacOSButton(); }
    public TextField createTextField() { return new MacOSTextField(); }
}

var factory = new WindowsFactory(); // Swap to MacOSFactory for macOS
var button = factory.createButton();
var textField = factory.createTextField();
button.render();
textField.render(); // Both are Windows-themed

interface DocumentParser {
    void parse(String filePath);
}

class PDFParser implements DocumentParser {
    public void parse(String filePath) {
        System.out.println("Parsing PDF: " + filePath);
    }
}

class WordParser implements DocumentParser {
    public void parse(String filePath) {
        System.out.println("Parsing Word doc: " + filePath);
    }
}

abstract class DocumentProcessor {
    protected abstract DocumentParser createParser(); // Factory method

    public void process(String filePath) {
        var parser = createParser(); // Delegates to subclass
        parser.parse(filePath);
        System.out.println("Processing complete.");
    }
}

class PDFProcessor extends DocumentProcessor {
    protected DocumentParser createParser() {
        return new PDFParser(); // Concrete factory method
    }
}

class WordProcessor extends DocumentProcessor {
    protected DocumentParser createParser() {
        return new WordParser();
    }
}

var processor = new PDFProcessor();
processor.process("invoice.pdf"); // Uses PDFParser

interface PaymentProcessor {
    void process(String orderId, double amount);
}

class StripeProcessor implements PaymentProcessor {
    public void process(String orderId, double amount) {
        // Real Stripe API call
    }
}

interface PaymentFactory {
    PaymentProcessor createProcessor();
}

class ProductionPaymentFactory implements PaymentFactory {
    public PaymentProcessor createProcessor() {
        return new StripeProcessor(); // Real implementation
    }
}

class OrderService {
    private final PaymentFactory factory;

    public OrderService(PaymentFactory factory) {
        this.factory = factory; // Injected, testable
    }

    public void checkout(String orderId, double amount) {
        var processor = factory.createProcessor();
        processor.process(orderId, amount);
    }
}

// In test
class TestPaymentFactory implements PaymentFactory {
    public PaymentProcessor createProcessor() {
        return mock(PaymentProcessor.class); // Mock for testing
    }
}

var service = new OrderService(new TestPaymentFactory());
service.checkout("ORD123", 99.99); // Uses mock, no real API call
